/**
 * 系列专题定义
 *
 * 系列归属由文章 frontmatter 的 `series: <id>` 显式声明（刻意决策：不再从
 * tags 推导——tag 只做横切知识索引，归属归 series 字段独占）。
 * 新增系列 = 在此登记一条 SeriesDef + 文章 frontmatter 挂上对应 id。
 * 系列内顺序 = 日期升序，「第 N 篇」= 该顺序中的序号（见 gatsby-node.ts）。
 */

export interface SeriesDef {
  /** url slug，对应 /series/<id>/；文章 frontmatter series 字段的合法取值 */
  id: string
  /** 系列名（渲染时由模板加《》） */
  title: string
  description: string
}

