export function getSeriesById(id: string): SeriesDef | null {
  return SERIES.find((s) => s.id === id) ?? null
}

/**
 * 按 frontmatter.series 查系列；未注册或为空返回 null。
 */
export function findSeriesForPost(
  seriesId: string | null | undefined
): SeriesDef | null {
  if (!seriesId) {
    return null
  }
  return getSeriesById(seriesId)
}

