import React from "react"
import { Link, graphql, PageProps } from "gatsby"
import { ArrowLeft, BookOpen, Calendar } from "@phosphor-icons/react"
import Layout from "../components/layout"
import SEO from "../components/seo"
import { Reveal } from "../components/animations"
import { getSeriesById } from "../data/series"

interface SeriesDetailPageContext {
  seriesId: string
}

interface PostNode {
  node: {
    fields: {
      slug: string
    }
    frontmatter: {
      title: string
      date: string
      description?: string
    }
  }
}

interface SeriesDetailData {
  site: {
    siteMetadata: {
      title: string
    }
  }
  allMarkdownRemark: {
    totalCount: number
    edges: PostNode[]
  }
}

/**
 * 系列封面页：系列简介 + 有序文章目录（日期升序，序号即「第 N 篇」）。
 * 阅读进度不持久化，纯静态。
 */
const SeriesDetailTemplate: React.FC<
  PageProps<SeriesDetailData, SeriesDetailPageContext>
> = ({ pageContext, data, location }) => {
  const series = getSeriesById(pageContext.seriesId)
  const { edges, totalCount } = data.allMarkdownRemark
  const siteTitle = data.site.siteMetadata.title

  if (!series) {
    return null
  }

  return (
    <Layout location={location} title={siteTitle}>
      <SEO
        title={`系列: ${series.title}`}
        description={series.description}
        keywords={[series.title, "系列", "series", "blog"]}
      />

      <div className="max-w-3xl mx-auto">
        {/* Back Link */}
        <div className="mb-6 fade-in">
          <Link
            to="/series/"
            className="inline-flex items-center gap-1.5 text-xs text-foreground-muted hover:text-accent transition-colors duration-200 group"
          >
            <ArrowLeft
              className="w-3.5 h-3.5 transition-transform duration-200 group-hover:-translate-x-1"
              weight="duotone"
            />
            返回所有系列
          </Link>
        </div>

        {/* Series Header */}
        <header className="mb-10 fade-in">
          <div className="flex items-start gap-4">
            <div className="flex items-center justify-center w-12 h-12 rounded-2xl bg-accent-subtle shrink-0">
              <BookOpen className="w-6 h-6 text-accent" weight="duotone" />
            </div>
            <div>
              <h1
                className="text-2xl sm:text-3xl font-bold text-foreground mb-2"
                style={{ fontFamily: '"Noto Serif SC", Georgia, serif' }}
              >
                《{series.title}》
              </h1>
              <p className="text-sm text-foreground-secondary leading-relaxed mb-2">
                {series.description}
              </p>
              <p className="text-xs text-foreground-muted">
                共{" "}
                <span className="text-accent font-semibold">{totalCount}</span>{" "}
                篇文章，按写作时间排序
              </p>
            </div>
          </div>
        </header>

        {/* Ordered Article List */}
        {edges.length === 0 ? (
          <div className="text-center py-16 fade-in">
            <div className="inline-flex items-center justify-center w-16 h-16 rounded-full bg-background-secondary mb-3">
              <BookOpen
                className="w-8 h-8 text-foreground-muted"
                weight="duotone"
              />
            </div>
            <p className="text-foreground-secondary text-sm">暂无文章</p>
          </div>
        ) : (
          <ol className="space-y-3">
            {edges.map(({ node }, index) => (
              <li key={node.fields.slug}>
                <Reveal delay={(index % 4) as 0 | 1 | 2 | 3}>
                  <Link
                    to={node.fields.slug}
                    className="group flex items-start gap-3.5 p-4 rounded-2xl bg-background-card shadow-xs hover:shadow-md transition-all duration-200"
                  >
                    <span
                      className="flex items-center justify-center w-7 h-7 rounded-full bg-accent-subtle text-accent text-xs font-semibold shrink-0 mt-0.5"
                      aria-label={`第 ${index + 1} 篇`}
                    >
                      {index + 1}
                    </span>
                    <span className="min-w-0">
                      <span className="block text-sm font-medium text-foreground group-hover:text-accent transition-colors duration-200">
                        {node.frontmatter.title}
                      </span>
                      <span className="mt-1 inline-flex items-center gap-1 text-[11px] text-foreground-muted">
                        <Calendar className="w-3 h-3" weight="duotone" />
                        <time>{node.frontmatter.date}</time>
                      </span>
                    </span>
                  </Link>
                </Reveal>
              </li>
            ))}
          </ol>
        )}
      </div>
    </Layout>
  )
}

export default SeriesDetailTemplate

export const pageQuery = graphql`
  query SeriesDetail($seriesId: String) {
    site {
      siteMetadata {
        title
      }
    }
    allMarkdownRemark(
      limit: 2000
      sort: { frontmatter: { date: ASC } }
      filter: {
        fileAbsolutePath: { regex: "/content/blog/" }
        frontmatter: { series: { eq: $seriesId }, published: { ne: false } }
      }
    ) {
      totalCount
      edges {
        node {
          fields {
            slug
          }
          frontmatter {
            title
            date(formatString: "YYYY年MM月DD日")
            description
          }
        }
      }
    }
  }
`
